import { createGameEngine } from './engine.js';
import { beastArt, mountainArt } from './art.js';

const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const safeJSON = value => JSON.stringify(value).replace(/[<>&\u2028\u2029]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));

/** Return a complete, offline-capable HTML document; safe for iframe.srcdoc. */
export function renderGame(options = {}) {
  const engine = createGameEngine(options);
  const { config } = engine;
  return `<!doctype html><html lang="${config.language === 'en' ? 'en' : 'zh-CN'}"><head><meta charset="utf-8"><!--\nMIT License\n\nCopyright (c) 2026 a348579184\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the "Software"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\nAll six spirit illustrations are original SVG artwork created for this game.\n--><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>${escapeHTML(config.title)}</title><style>${STYLES}</style></head><body><div class="ambient" aria-hidden="true"></div><div id="game-root"></div><div id="battle-root"></div><dialog id="modal" aria-labelledby="modal-title"></dialog><div id="toast" class="toast" role="status" aria-live="polite"></div><script type="application/json" id="mist-save">null</script><script>(${bootGame.toString()})(${safeJSON(config)},${createGameEngine.toString()},${beastArt.toString()},${mountainArt.toString()});</script></body></html>`;
}

function bootGame(config, createEngine, art, mountains) {
  'use strict';
  const engine = createEngine(config), en = config.language === 'en';
  const t = (zh, english) => en ? english : zh;
  const esc = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const root = document.getElementById('game-root'), battleRoot = document.getElementById('battle-root'), modal = document.getElementById('modal');
  const key = engine.gameId; let storageAvailable = true, damagedSave = false, state;
  try { const saved = localStorage.getItem(key); if (saved) { state = engine.deserializeState(saved); if (!state) damagedSave = true; } } catch { storageAvailable = false; }
  if (!state) { try { state = engine.deserializeState(document.getElementById('mist-save').textContent); } catch { /* No embedded save. */ } }
  state ||= engine.createInitialState();
  let selected = state.party[0], activeBattle = null, timer = null, toastTimer = null, speed = 1;
  const reducedMotion = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const beastFor = card => engine.beasts.find(b => b.id === card.beast);
  const itemName = item => en ? item.en : item.name;
  const stageName = stage => en ? stage.en : stage.name;
  const stars = n => '★'.repeat(n) + '☆'.repeat(3 - n);
  const icon = name => ({ leaf: '❧', coin: '◈', sword: '↗', heart: '♡', armor: '◇', close: '×' }[name] || name);
  function toast(message) { clearTimeout(toastTimer); const el = document.getElementById('toast'); el.textContent = message; el.classList.add('visible'); toastTimer = setTimeout(() => el.classList.remove('visible'), 3600); }
  function save() { try { localStorage.setItem(key, engine.serializeState(state)); storageAvailable = true; } catch { storageAvailable = false; } }
  function commit(next) { state = next; if (!state.cards.some(c => c.id === selected)) selected = state.party[0]; save(); render(); }
  const tag = (text, cls = '') => `<span class="tag ${cls}">${esc(text)}</span>`;
  function renderCard(card, index) {
    const beast = beastFor(card), stats = engine.cardStats(state, card), deployed = state.party.includes(card.id), chosen = selected === card.id;
    return `<article class="spirit-card ${chosen ? 'selected' : ''} ${deployed ? 'deployed' : ''}" style="--beast:${beast.color}" data-testid="card-${card.id}"><div class="card-corners" aria-hidden="true"></div><button class="card-select" id="select-${card.id}" data-action="select" data-id="${card.id}" aria-pressed="${chosen}" aria-label="${esc(beast.name + ' ' + card.star + t('星，选择灵兽', ' star, select spirit'))}"><span class="card-top"><span class="stars" aria-label="${card.star} ${t('星', 'stars')}">${stars(card.star)}</span><span class="card-index">${String(index + 1).padStart(2, '0')}</span></span><span class="beast-art">${art(card.beast, beast.color, card.id)}</span><span class="beast-name">${esc(beast.name)}</span><span class="beast-skill">${esc(en ? beast.skillEn : beast.skill)}</span><span class="card-stats"><span title="${t('攻击', 'Attack')}" aria-label="${t('攻击', 'Attack')} ${stats.attack}">${icon('sword')} ${stats.attack}</span><span title="${t('生命', 'Health')}" aria-label="${t('生命', 'Health')} ${stats.health}">${icon('heart')} ${stats.health}</span><span title="${t('护甲', 'Armor')}" aria-label="${t('护甲', 'Armor')} ${stats.armor}">${icon('armor')} ${stats.armor}</span></span></button><div class="card-bottom"><span class="equipped-label" title="${stats.item ? esc(itemName(engine.items.find(i => i.id === stats.item))) : ''}">${stats.item ? '✧ ' + esc(itemName(engine.items.find(i => i.id === stats.item))) : t('未佩灵器', 'No relic')}</span><button class="deploy-button ${deployed ? 'on' : ''}" id="party-${card.id}" data-action="party" data-id="${card.id}" data-testid="party-${card.id}" aria-label="${esc((deployed ? t('收回 ', 'Bench ') : t('出阵 ', 'Deploy ')) + beast.name)}" aria-pressed="${deployed}">${deployed ? '✓ ' + t('出阵', 'Party') : '+ ' + t('出阵', 'Deploy')}</button></div></article>`;
  }
  function render() {
    const focusId = document.activeElement?.id;
    const groups = engine.mergeGroups(state), selectedCard = state.cards.find(c => c.id === selected) || state.cards[0], beast = beastFor(selectedCard);
    const completed = state.cleared === 3;
    const objective = completed ? t('山海已明，灵契长存。你的雾岭之旅已圆满。', 'The mountains shine again. Your covenant is complete.') : groups.length ? t('灵契共鸣已就绪：三只同名同星灵兽，可以合成更高星级。', 'A covenant resonates: merge three matching spirits of the same star tier.') : state.cleared === 0 ? t('为出阵灵兽佩上灵器，然后出发「苔径初行」。', 'Equip your party with relics, then explore The Moss Path.') : t('首通奖励带来了新伙伴。合成、佩器，继续走向云巅。', 'First-clear gifts bring new companions. Merge, equip, and climb higher.');
    root.innerHTML = `<div class="app-shell"><header class="topbar"><a class="brand" href="#main" aria-label="${esc(config.title)}"><span class="brand-mark" aria-hidden="true">契</span><span><strong>${esc(config.title)}</strong><small>${t('山海之间 · 万物有灵', 'BETWEEN MOUNTAIN & MIST')}</small></span></a><nav class="top-actions" aria-label="${t('游戏菜单', 'Game menu')}"><button class="text-button" data-action="guide" id="guide" data-testid="help-button">${t('玩法手札', 'Field guide')}</button><button class="text-button" data-action="download" id="download" data-testid="download-button">↓ <span>${t('离线珍藏', 'Keep offline')}</span></button><button class="icon-button" data-action="reset" id="reset" data-testid="reset-button" aria-label="${t('重新开始游戏', 'Reset game')}" title="${t('重新开始', 'Reset game')}">↺</button></nav></header><main id="main"><section class="hero" aria-labelledby="hero-title"><div class="mountains">${mountains()}</div><div class="hero-copy"><div class="eyebrow"><span></span>${t('雾散之处，灵契初生', 'A LITTLE WONDER IN THE WILDS')}</div><h1 id="hero-title">${completed ? t('云开见月，<em>归契山海。</em>', 'Mist lifts.<em>The mountain remembers.</em>') : t('与山灵，<em>结一场奇遇。</em>', 'Meet the spirits.<em>Make a little magic.</em>')}</h1><p>${t('召来六方山灵，融合同源灵契。<br>带上你的伙伴，走过这片温柔而神秘的雾岭。', 'Gather six mountain spirits. Unite their ancient gifts.<br>With your companions, find a path through the mist.')}</p><div class="hero-meta">${tag(t('原创灵兽', 'ORIGINAL SPIRITS'))}${tag(t('三境探索', 'THREE CHAPTERS'))}${tag(t('无尽温柔 · 无需氪金', 'NO GRIND · NO PURCHASES'))}</div></div><div class="summon-panel"><div class="summon-top"><span class="eyebrow">${t('山间灵泉', 'THE SPIRIT SPRING')}</span><span class="currency" data-testid="gold">◈ <strong>${state.gold}</strong><small>${t('灵露', 'dew')}</small></span></div><div class="summon-sigil" aria-hidden="true"><span>✧</span><i></i><b>契</b></div><button class="primary summon-button" data-action="draw" id="draw" data-testid="draw-button" ${state.gold < 12 || state.cards.length >= 114 ? 'disabled' : ''}>${t('唤灵结契', 'Summon a spirit')} <span>◈ 12</span></button><p class="fine-print">${t('每次唤来一位一星灵兽 · 六灵等概率', 'One one-star spirit · six equally likely companions')}</p></div></section><section class="quest-strip ${completed ? 'complete' : ''}" aria-label="${t('当前目标', 'Current objective')}"><span class="quest-icon">${completed ? '✦' : '❧'}</span><div><strong>${completed ? t('灵契圆满', 'Covenant complete') : t('行山小笺', 'A note for the journey')}</strong><span>${objective}</span></div><span class="chapter-progress">${state.cleared} / 3 <span>${t('山印', 'seals')}</span></span></section><div class="main-grid"><section class="collection" aria-labelledby="collection-title"><div class="section-heading"><div><div class="eyebrow">${t('与你同行', 'YOUR COMPANIONS')}</div><h2 id="collection-title">${t('灵兽图卷', 'Spirit collection')} <span>${state.cards.length.toString().padStart(2, '0')}</span></h2></div><button class="subtle-button" data-action="auto" id="auto-party" data-testid="auto-party">${t('自动布阵', 'Best formation')} ↗</button></div><div class="party-strip"><span class="party-label">${t('出阵', 'PARTY')} <b>${state.party.length}/4</b></span><div class="party-list">${state.party.map((id, i) => { const card = state.cards.find(c => c.id === id); return `<button data-action="select" data-id="${id}" aria-label="${esc(t('阵位 ', 'Position ') + (i + 1) + ' ' + beastFor(card).name)}" class="party-chip ${selected === id ? 'active' : ''}"><span>${i === 0 ? '◇' : i + 1}</span>${esc(beastFor(card).name)}<small>${'★'.repeat(card.star)}</small></button>`; }).join('')}</div><span class="frontline-note">${t('左侧先承伤', 'Left takes hits first')}</span></div><div class="merge-bar ${groups.length ? 'ready' : ''}" data-testid="merge-panel"><span>${groups.length ? '✦ ' + t('同源共鸣', 'Ready to merge') : '◇ ' + t('三只同名、同星 → 升一星（最高三星）', 'Three matching spirits → next tier (max 3★)')}</span>${groups.map(g => `<button class="merge-button" id="merge-${g.beast}-${g.star}" data-action="merge" data-beast="${g.beast}" data-star="${g.star}" data-testid="merge-button">${esc(engine.beasts.find(b => b.id === g.beast).name)} ×3 <span>→ ${g.star + 1}★</span></button>`).join('')}</div><div class="cards-grid">${state.cards.map(renderCard).join('')}</div><section class="inspector" aria-labelledby="selected-name" data-testid="selected-card"><div class="inspector-art">${art(selectedCard.beast, beast.color, 'detail')}</div><div class="inspector-copy"><div class="eyebrow">${t('灵兽志', 'SPIRIT NOTES')} · ${esc(en ? beast.skillEn : beast.skill)}</div><h3 id="selected-name">${esc(beast.name)} <span class="stars">${stars(selectedCard.star)}</span></h3><p>${esc(beast.description)}</p><p class="skill-detail">${esc(en ? beast.detailEn : beast.detail)}</p>${state.party.includes(selected) && state.party[0] !== selected ? `<button class="text-button" data-action="front" id="move-front">${t('移至前排承伤', 'Move to the front line')} →</button>` : ''}</div></section><section class="equipment" aria-labelledby="equipment-title"><div class="section-heading compact"><div><div class="eyebrow">${t('山川赠礼', 'GIFTS OF THE MOUNTAIN')}</div><h2 id="equipment-title">${t('灵器行囊', 'Relic satchel')}</h2></div><span class="section-note">${t('每位灵兽可佩一件', 'One relic per spirit')}</span></div><div class="equipment-grid">${engine.items.map(item => { const unlocked = state.ownedItems.includes(item.id), holder = state.cards.find(c => c.id === state.equipment[item.id]); return `<div class="relic ${unlocked ? '' : 'locked'}"><span class="relic-icon" aria-hidden="true">${item.icon}</span><div class="relic-copy"><h3>${esc(itemName(item))}</h3><p>${esc(en ? item.descriptionEn : item.description)}</p><span>${holder ? esc(beastFor(holder).name) + ' · ' + t('已佩戴', 'equipped') : unlocked ? t('静候有缘灵兽', 'Awaiting a companion') : t('通关第 ', 'Clear chapter ') + (item.id === 'bell' ? '1' : '2') + t(' 境解锁', ' to unlock')}</span></div>${unlocked ? `<div class="relic-actions"><button class="subtle-button" data-action="equip" data-item="${item.id}" id="equip-${item.id}" data-testid="equip-${item.id}" aria-label="${esc(t('给', 'Equip ') + beast.name + t('佩戴', ' with ') + itemName(item))}" ${holder?.id === selected ? 'disabled' : ''}>${t('给所选灵兽', 'Equip selected')}</button>${holder ? `<button class="text-button" data-action="unequip" data-item="${item.id}" id="unequip-${item.id}" aria-label="${esc(t('卸下', 'Remove ') + itemName(item))}">${t('卸下', 'Remove')}</button>` : ''}</div>` : '<span class="lock-symbol" aria-hidden="true">◇</span>'}</div>`; }).join('')}</div></section></section><aside class="journey" aria-labelledby="journey-title"><div class="section-heading"><div><div class="eyebrow">${t('循雾而行', 'FOLLOW THE MIST')}</div><h2 id="journey-title">${t('雾岭三境', 'The mountain trail')}</h2></div><span class="trail-mark" aria-hidden="true">山</span></div><div class="stages">${engine.availableStages(state).map(stage => `<article class="stage ${stage.unlocked ? '' : 'locked'} ${stage.completed ? 'cleared' : ''}" data-testid="stage-${stage.id}"><div class="stage-number">0${stage.id}<span>${stage.completed ? '✓' : stage.unlocked ? '✦' : '◇'}</span></div><div class="stage-landscape landscape-${stage.id}" aria-hidden="true"><i></i><b></b><span></span></div><div class="stage-content"><div class="stage-status">${stage.completed ? t('山印已得', 'SEAL RECOVERED') : stage.unlocked ? t('此境已开启', 'READY TO EXPLORE') : t('前境通关后开启', 'CLEAR PREVIOUS CHAPTER')}</div><h3>${esc(stageName(stage))}</h3><p>${esc(en ? stage.subtitleEn : stage.subtitle)}</p><div class="stage-reward">${t('首通', 'First clear')} <span>◈ ${stage.reward}</span>${stage.id < 3 ? ' · ' + t('灵兽 ×2 · 灵器', '2 spirits · a relic') : ' · ' + t('山海圆契', 'the final covenant')}</div><button class="${stage.unlocked && !stage.completed ? 'primary' : 'stage-button'}" data-action="battle" data-stage="${stage.id}" id="stage-button-${stage.id}" data-testid="battle-${stage.id}" ${stage.unlocked ? '' : 'disabled'}>${stage.completed ? t('重访此境', 'Revisit chapter') : stage.unlocked ? t('携灵入境', 'Enter the mist') : t('云雾未散', 'Veiled in mist')}<span>${stage.unlocked ? '→' : '◇'}</span></button></div></article>`).join('')}</div><div class="trail-note"><span aria-hidden="true">☽</span><p>${t('战斗自动进行，伙伴每战满血。<br>失利不损失灵露，重访不重复领奖。<br>合成与灵器，比盲目唤灵更重要。', 'Battles play automatically; spirits start fully healed.<br>Defeat costs nothing. Rewards are first-clear only.<br>Merging and relics matter more than endless summons.')}</p></div>${state.lastBattle ? `<div class="last-battle" data-testid="last-battle"><strong>${state.lastBattle.won ? '✦ ' + t('上次凯旋', 'Last victory') : '◇ ' + t('上次历练', 'Last expedition')}</strong><span>${esc(stageName(engine.stages[state.lastBattle.stage - 1]))} · ${state.lastBattle.rounds} ${t('回合', 'rounds')}</span></div>` : ''}</aside></div></main><footer><span><i class="save-dot ${storageAvailable ? '' : 'warning'}"></i><span data-testid="save-status">${storageAvailable ? t('进度已自动珍藏于此浏览器', 'Progress saved in this browser') : t('浏览器存储不可用 · 请下载离线珍藏保留进度', 'Storage unavailable · download to keep your progress')}</span></span><span class="seed-label">${t('山岚种子', 'WORLD SEED')} <code>${esc(config.seed)}</code></span><span>${t('六灵皆为原创 · 无联网请求', 'Six original spirits · entirely offline')}</span></footer></div>`;
    if (focusId) document.getElementById(focusId)?.focus({ preventScroll: true });
  }
  function errorMessage(error) {
    const map = { NOT_ENOUGH_GOLD: t('灵露不足。首通山境可获得更多灵露。', 'Not enough dew. Clear a new chapter to earn more.'), COLLECTION_FULL: t('图卷已满，请先合成灵兽。', 'Collection full. Merge spirits to make room.'), INVALID_PARTY: t('请保留 1 至 4 位出阵灵兽。', 'Keep between one and four spirits in your party.'), STAGE_LOCKED: t('先通关前一境，雾才会散。', 'Clear the previous chapter first.'), MERGE_MISMATCH: t('需要三只同名、同星的灵兽。', 'Merge three matching spirits at the same star tier.') };
    return map[error.message] || t('这次操作未能完成，请重试。', 'That action could not be completed. Please try again.');
  }
  function openModal(content) { modal.innerHTML = content; modal.showModal(); }
  function guide() {
    openModal(`<div class="dialog-heading"><span class="eyebrow">${t('一卷行山手札', 'A TRAVELER’S FIELD GUIDE')}</span><button class="icon-button" data-dialog="close" aria-label="${t('关闭', 'Close')}">×</button></div><h2 id="modal-title">${t('与六灵，慢慢相识。', 'A covenant, one companion at a time.')}</h2><div class="guide-steps"><p><b>01 · ${t('先合成', 'Merge first')}</b>${t('开局已有三只一星青岚鹿。点击「同源共鸣」将它们合为一只二星灵兽，战力大幅提升。最高可达三星；佩戴的灵器会保留一件，其余回到行囊。', 'You begin with three one-star Jadeharts. Merge them into a stronger two-star spirit. The maximum tier is three stars. One equipped relic is retained; any others return to your satchel.')}</p><p><b>02 · ${t('再布阵', 'Form your party')}</b>${t('最多四位灵兽出阵，左侧先承受攻击。选中灵兽后可佩戴灵器、移到前排；每位可佩一件。自动布阵会优先选择强大的伙伴。', 'Deploy up to four spirits. The leftmost takes hits first. Select a spirit to equip a relic or move it to the front. Each holds one relic. Best formation selects your strongest companions.')}</p><p><b>03 · ${t('入境探索', 'Explore the trail')}</b>${t('每场战斗自动进行，三回合触发部分灵技。每战开始恢复全部生命，失败不消耗资源。首通第一、二境各赠同源灵兽两只及一件灵器，足以让队伍不断成长。', 'Battles run automatically, with several skills triggering every third round. Everyone starts at full health; defeats cost nothing. The first two chapters each grant two matching spirits and a relic—enough to grow without grinding.')}</p><p><b>04 · ${t('珍藏旅程', 'Keep your journey')}</b>${t('每次操作都会自动保存。离线珍藏会下载包含当前存档的完整 HTML 文件，双击即可继续，无需联网。清除浏览器数据会删除本地进度；重置前会再次确认。', 'Every action is saved automatically. Keep offline downloads the complete game with your current save; open the HTML file to continue without a connection. Clearing browser data removes local saves. Reset always asks for confirmation.')}</p></div><button class="primary" data-dialog="close">${t('记下了，出发吧', 'Got it. Let’s explore.')}</button>`);
  }
  function askReset() {
    openModal(`<div class="dialog-heading"><span class="eyebrow">${t('重启山间奇遇', 'A FRESH BEGINNING')}</span><button class="icon-button" data-dialog="close" aria-label="${t('取消', 'Cancel')}">×</button></div><h2 id="modal-title">${t('让一切回到初见？', 'Begin the journey again?')}</h2><p class="dialog-copy">${t('这将清除当前灵兽、灵器与山境进度。山岚种子不变。你可以先下载离线珍藏，留下这段旅程。', 'This clears your spirits, relics, and chapter progress. The world seed stays the same. Download an offline copy first if you’d like to keep this journey.')}</p><div class="dialog-actions"><button class="subtle-button" data-dialog="close" data-testid="cancel-reset">${t('继续这段旅程', 'Keep my journey')}</button><button class="danger-button" data-dialog="confirm-reset" data-testid="confirm-reset">${t('确认重新开始', 'Reset my progress')}</button></div>`);
  }
  function download() {
    const copy = document.documentElement.cloneNode(true);
    copy.querySelector('#mist-save').textContent = engine.serializeState(state).replace(/</g, '\\u003c');
    copy.querySelector('#modal').removeAttribute('open'); copy.querySelector('#modal').innerHTML = ''; copy.querySelector('#battle-root').innerHTML = ''; copy.querySelector('#toast').className = 'toast'; copy.querySelector('#toast').textContent = '';
    const blob = new Blob(['<!doctype html>\n' + copy.outerHTML], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = config.title.replace(/[\\/:*?"<>|\u0000-\u001f]/g, '_').slice(0, 64) + '.html'; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(t('完整游戏与当前存档已打包。愿山灵一路相伴。', 'Your complete game and save are packed for an offline journey.'));
  }
  function battleUnit(unit, side) {
    const beast = side === 'ally' ? engine.beasts.find(b => b.id === unit.beast) : null;
    return `<div class="battle-unit ${side}" data-unit="${unit.id}"><div class="battle-portrait">${beast ? art(unit.beast, beast.color, 'battle-' + unit.id) : `<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M20 72L32 43 27 28 43 34 51 18 61 35 79 30 72 48 84 72 65 84 39 86Z" fill="#445c64" stroke="#8fa8b1"/><path d="M31 58L43 61M60 61L72 55" stroke="#d8c48b" stroke-width="3"/><path d="M44 74Q53 69 62 72" fill="none" stroke="#aec5c4"/></svg>`}</div><strong>${esc(unit.name)}</strong><div class="health-track" role="meter" aria-label="${esc(unit.name)} ${t('生命', 'health')}" aria-valuemin="0" aria-valuemax="${unit.health}" aria-valuenow="${unit.hp}"><i style="width:${unit.hp / unit.health * 100}%"></i></div><small data-hp="${unit.id}">${unit.hp} / ${unit.health}</small><span class="floating-damage" aria-hidden="true"></span></div>`;
  }
  function beginBattle(stageId) {
    const result = engine.startBattle(state, stageId); commit(result.state);
    activeBattle = { ...result.battle, cursor: 0, units: [...result.battle.allies, ...result.battle.enemies].map(u => ({ ...u })), done: false };
    root.inert = true;
    battleRoot.innerHTML = `<div class="battle-backdrop"><section class="battle-dialog" role="dialog" aria-modal="true" aria-labelledby="battle-title" tabindex="-1"><div class="battle-header"><div><div class="eyebrow">${t('灵契交锋', 'COVENANTS IN MOTION')}</div><h2 id="battle-title">${esc(stageName(engine.stages[stageId - 1]))}</h2></div><div class="battle-controls"><button class="subtle-button" data-battle="speed" data-testid="battle-speed">1×</button><button class="text-button" data-battle="skip" data-testid="skip-battle">${t('快进至结果', 'Skip to result')} →</button></div></div><div class="battle-round" data-testid="battle-round">${t('灵兽蓄势，雾境初开', 'Spirits gather. The mist opens.')}<span></span></div><div class="battle-field"><div class="battle-team allies">${activeBattle.allies.map(u => battleUnit(u, 'ally')).join('')}</div><div class="versus" aria-hidden="true">✧</div><div class="battle-team enemies">${activeBattle.enemies.map(u => battleUnit(u, 'enemy')).join('')}</div></div><div class="battle-log" role="log" aria-label="${t('战斗记录', 'Battle log')}" aria-live="off" data-testid="battle-log"></div><div class="battle-result" data-testid="battle-result"></div></section></div>`;
    battleRoot.querySelector('.battle-dialog').focus();
    timer = setTimeout(battleStep, reducedMotion ? 80 : 550);
  }
  function updateUnit(id, remaining, amount, heal, fast) {
    const unit = activeBattle.units.find(u => u.id === id); unit.hp = remaining;
    const el = battleRoot.querySelector(`[data-unit="${id}"]`), meter = el.querySelector('[role="meter"]'); meter.setAttribute('aria-valuenow', String(remaining)); meter.querySelector('i').style.width = remaining / unit.health * 100 + '%';
    el.querySelector('[data-hp]').textContent = remaining + ' / ' + unit.health; el.classList.toggle('fallen', remaining === 0);
    if (!fast && !reducedMotion) { const number = el.querySelector('.floating-damage'); number.textContent = (heal ? '+' : '−') + amount; number.classList.toggle('healing', heal); number.classList.remove('animate'); void number.offsetWidth; number.classList.add('animate'); }
  }
  function applyEvent(event, fast) {
    const log = battleRoot.querySelector('.battle-log');
    if (event.kind === 'round') { battleRoot.querySelector('.battle-round').textContent = t('第 ', 'Round ') + event.round + t(' 回合', ''); const row = document.createElement('p'); row.className = 'log-round'; row.textContent = '— ' + t('第 ', 'Round ') + event.round + t(' 回合', '') + ' —'; log.append(row); }
    else {
      const actor = activeBattle.units.find(u => u.id === event.actor), target = activeBattle.units.find(u => u.id === event.target);
      updateUnit(event.target, event.remaining, event.amount, event.kind === 'heal', fast);
      const row = document.createElement('p'); row.className = event.kind === 'heal' ? 'log-heal' : event.side === 'enemy' ? 'log-enemy' : 'log-ally';
      row.textContent = event.kind === 'heal' ? t(`${actor.name} 为 ${target.name} 恢复 ${event.amount} 点生命`, `${actor.name} heals ${target.name} for ${event.amount}`) : t(`${actor.name}${event.skill ? ' 施展灵技，' : ' → '}${target.name} −${event.amount}${event.remaining === 0 ? ' · 退场' : ''}`, `${actor.name}${event.skill ? ' uses a skill on ' : ' → '}${target.name} −${event.amount}${event.remaining === 0 ? ' · fallen' : ''}`);
      log.append(row);
    }
    log.scrollTop = log.scrollHeight;
  }
  function battleStep() {
    if (!activeBattle || activeBattle.done) return;
    if (activeBattle.cursor >= activeBattle.events.length) { finishBattle(); return; }
    const event = activeBattle.events[activeBattle.cursor++]; applyEvent(event, false);
    timer = setTimeout(battleStep, (event.kind === 'round' ? 580 : 330) / speed);
  }
  function finishBattle() {
    clearTimeout(timer); timer = null; if (!activeBattle) return;
    activeBattle.done = true;
    const b = activeBattle; const box = battleRoot.querySelector('.battle-result');
    box.innerHTML = `<div class="result-mark">${b.won ? '✦' : '☽'}</div><div><h3>${b.won ? b.stage === 3 && b.firstClear ? t('雾散月明，灵契圆满！', 'The mist lifts. Your covenant is complete!') : t('山境已明，携灵而归。', 'A seal recovered. A path revealed.') : t('暂歇一程，再赴山海。', 'Rest a while. The mountain will wait.')}</h3><p>${b.won ? b.firstClear ? t(`首通奖励：灵露 +${b.rewards.gold}`, `First-clear reward: +${b.rewards.gold} dew`) + (b.rewards.cards.length ? t(' · 同源灵兽 ×2 · 新灵器 ×1', ' · 2 matching spirits · 1 new relic') : '') : t('重访不重复获得奖励。伙伴们又多了一段山间回忆。', 'No repeat rewards, just another memory of the mountain.') : t('没有失去任何资源。试试合成升星、佩戴灵器，并让高生命伙伴站在前排。', 'Nothing was lost. Try merging, equipping relics, and putting a sturdy spirit in front.')}</p><small>${b.rounds} ${t('回合 · 全体伙伴已恢复生命', 'rounds · all companions fully restored')}</small></div><button class="primary" data-battle="close" data-testid="close-battle">${t('回到山间', 'Back to the trail')} →</button>`;
    battleRoot.querySelector('.battle-controls').hidden = true;
    box.setAttribute('role', 'status'); box.querySelector('button').focus({ preventScroll: true });
  }
  function skipBattle() { if (!activeBattle || activeBattle.done) return; clearTimeout(timer); while (activeBattle.cursor < activeBattle.events.length) applyEvent(activeBattle.events[activeBattle.cursor++], true); finishBattle(); }
  root.addEventListener('click', event => {
    const button = event.target.closest('[data-action]'); if (!button || button.disabled || activeBattle) return;
    try {
      const action = button.dataset.action;
      if (action === 'select') { selected = button.dataset.id; render(); }
      if (action === 'draw') { const result = engine.drawCard(state); selected = result.card.id; commit(result.state); toast(t('灵契结成 · ', 'A covenant forms · ') + beastFor(result.card).name); document.getElementById('select-' + selected)?.scrollIntoView({ block: 'nearest', behavior: reducedMotion ? 'auto' : 'smooth' }); }
      if (action === 'merge') { const group = engine.mergeGroups(state).find(g => g.beast === button.dataset.beast && g.star === Number(button.dataset.star)); if (group) { const next = engine.mergeCards(state, group.ids); selected = next.cards.find(c => group.ids.includes(c.id)).id; commit(next); toast(t('同源归一，灵契升星！', 'Three become one. Your covenant grows!')); } }
      if (action === 'party') { const id = button.dataset.id; if (state.party.includes(id)) commit(engine.setParty(state, state.party.filter(c => c !== id))); else if (state.party.length >= 4) toast(t('阵位已满，请先收回一位伙伴，或使用自动布阵。', 'Your party is full. Bench a spirit first, or use Best formation.')); else commit(engine.setParty(state, [...state.party, id])); }
      if (action === 'auto') { commit(engine.autoParty(state)); toast(t('阵容已整备，坚实的伙伴站在最前方。', 'Formation ready, with a sturdy companion in front.')); }
      if (action === 'front') commit(engine.setParty(state, [selected, ...state.party.filter(id => id !== selected)]));
      if (action === 'equip') { commit(engine.equipItem(state, button.dataset.item, selected)); toast(t('灵器已佩戴，原有灵器自动回到行囊。', 'Relic equipped. Any previous relic returns to the satchel.')); }
      if (action === 'unequip') commit(engine.equipItem(state, button.dataset.item, null));
      if (action === 'battle') beginBattle(Number(button.dataset.stage));
      if (action === 'guide') guide(); if (action === 'reset') askReset(); if (action === 'download') download();
    } catch (error) { toast(errorMessage(error)); }
  });
  modal.addEventListener('click', event => { const action = event.target.closest('[data-dialog]')?.dataset.dialog; if (action === 'close') modal.close(); if (action === 'confirm-reset') { modal.close(); selected = 'c6'; commit(engine.createInitialState()); toast(t('山岚如初，新的奇遇已启程。', 'A fresh mist. A new beginning.')); } });
  battleRoot.addEventListener('click', event => {
    const button = event.target.closest('[data-battle]'); if (!button) return;
    if (button.dataset.battle === 'skip') skipBattle();
    if (button.dataset.battle === 'speed') { speed = speed === 1 ? 2 : speed === 2 ? 4 : 1; button.textContent = speed + '×'; }
    if (button.dataset.battle === 'close' && activeBattle?.done) { const stage = activeBattle.stage; activeBattle = null; battleRoot.innerHTML = ''; root.inert = false; document.getElementById('stage-button-' + stage)?.focus(); }
  });
  document.addEventListener('keydown', event => {
    if (!activeBattle) return;
    if (event.key === 'Escape') { event.preventDefault(); if (activeBattle.done) battleRoot.querySelector('[data-battle="close"]').click(); else skipBattle(); }
    if (event.key === 'Tab') { const focusable = [...battleRoot.querySelectorAll('button:not([disabled])')].filter(el => !el.closest('[hidden]')); const first = focusable[0], last = focusable[focusable.length - 1]; if (event.shiftKey && (document.activeElement === first || !focusable.includes(document.activeElement))) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && (document.activeElement === last || !focusable.includes(document.activeElement))) { event.preventDefault(); first?.focus(); } }
  });
  save(); render();
  if (damagedSave) toast(t('旧存档无法读取，已安全开启新旅程。', 'The previous save could not be read. A fresh journey is ready.'));
  window.__MISTBOUND_READY__ = true;
}

